def parse_xml(webhook_data):
    import xml.etree.ElementTree as ET
    root = ET.fromstring(webhook_data)
    parsed_data = []

    for child in root:
        data_dict = {}
        for element in child:
            if element.tag in data_dict:
                data_dict[element.tag] += ' ' + element.text
            else:
                data_dict[element.tag] = element.text
        parsed_data.append(data_dict)

