        self.period = period
        self.calls = {}

    async def wait_for_slot(self, user_id):
        if user_id in self.calls:
            timestamps = self.calls[user_id]
        else:
            timestamps = []
            self.calls[user_id] = timestamps

        while len(timestamps) >= self.limit:
